struct Particle {
    float position[3];
    float velocity[3];
};

void parallelUpdateParticlePositions(Particle *particles, const size_t particleCount, const size_t start, const size_t end, float h, float boxWidth, float elasticity, float g, float deltaTime) {
    for (size_t i = start; i < end; ++i) {
        particles[i].velocity[1] -= g * deltaTime;
        particles[i].position[0] += particles[i].velocity[0] * deltaTime;
        particles[i].position[1] += particles[i].velocity[1] * deltaTime;
        particles[i].position[2] += particles[i].velocity[2] * deltaTime;

        if (particles[i].position[0] < -boxWidth) {
            particles[i].velocity[0] = -particles[i].velocity[0] * elasticity;
            particles[i].position[0] = -boxWidth;
        } else if (particles[i].position[0] > boxWidth) {
            particles[i].velocity[0] = -particles[i].velocity[0] * elasticity;
            particles[i].position[0] = boxWidth;
        }

        if (particles[i].position[1] < -boxWidth) {
            particles[i].velocity[1] = -particles[i].velocity[1] * elasticity;
            particles[i].position[1] = -boxWidth;
        } else if (particles[i].position[1] > boxWidth) {
            particles[i].velocity[1] = -particles[i].velocity[1] * elasticity;
            particles[i].position[1] = boxWidth;
        }

        if (particles[i].position[2] < -boxWidth) {
            particles[i].velocity[2] = -particles[i].velocity[2] * elasticity;
            particles[i].position[2] = -boxWidth;
        } else if (particles[i].position[2] > boxWidth) {
            particles[i].velocity[2] = -particles[i].velocity[2] * elasticity;
            particles[i].position[2] = boxWidth;
        }
    }
}

int main() {
    Particle particles[10];
    size_t particleCount = 10;
    size_t start = 0;
    size_t end = particleCount;
    float h = 1.0f;
    float boxWidth = 10.0f;
    float elasticity = 0.5f;
    float g = 9.81f;
    float deltaTime = 0.01f;
    parallelUpdateParticlePositions(particles, particleCount, start, end, h, boxWidth, elasticity, g, deltaTime);
    return 0;
}
